//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/zip` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/zip_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_zip_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.
//! - Fixtures skipped by the generator: `bug51353` (unconditional php-src SKIPIF)
//!   and `gh17319` (PHP expects false from its own freed archive resource).
//!   They remain in `tests/php_src/zip/`; the generator records the reasons.

use super::{assert_format, run_case};
use crate::support::zip_native::skip_without_zip_native;

/// Replays php-src `001.phpt`.
#[test]
fn test_php_src_zip_001() {
    if skip_without_zip_native("test_php_src_zip_001") { return; }
    let out = run_case(r#"<?php
echo "zip extension is available";
"#, &[], &[]);
    assert_eq!(out, r#"zip extension is available"#);
}
/// Replays php-src `addGlob_default_options.phpt`.
#[test]
fn test_php_src_zip_addGlob_default_options() {
    if skip_without_zip_native("test_php_src_zip_addGlob_default_options") { return; }
    let out = run_case(r#"<?php
$dir = __DIR__ . '/addglob_default_options_dir';
@mkdir($dir);
$src = $dir . '/data.txt';
file_put_contents($src, str_repeat('The quick brown fox. ', 3000));
$archive = $dir . '/test.zip';

function stat_first(string $archive): array
{
    $zip = new ZipArchive();
    $zip->open($archive);
    $sb = $zip->statIndex(0);
    $zip->close();

    return $sb;
}

function add_glob(string $archive, string $pattern, mixed $options): bool
{
    $zip = new ZipArchive();
    $zip->open($archive, ZipArchive::CREATE | ZipArchive::OVERWRITE);
    $added = $options === null
        ? $zip->addGlob($pattern)
        : $zip->addGlob($pattern, 0, $options);
    $zip->close();

    return is_array($added);
}

/* comp_method defaults to "leave it to libzip", i.e. deflate, not CM_STORE. */
foreach (['no options' => null, 'empty options' => []] as $label => $options) {
    echo "-- $label --", PHP_EOL;
    @unlink($archive);
    var_dump(add_glob($archive, $dir . '/*.txt', $options));
    $sb = stat_first($archive);
    var_dump($sb['comp_method'] === ZipArchive::CM_DEFLATE);
    var_dump($sb['comp_size'] < $sb['size']);
}

/* flags defaults to FL_OVERWRITE, so an existing entry is replaced. */
echo '-- overwrites an existing entry --', PHP_EOL;
@unlink($archive);
$zip = new ZipArchive();
$zip->open($archive, ZipArchive::CREATE | ZipArchive::OVERWRITE);
$zip->addFromString($src, 'placeholder');
var_dump(is_array($zip->addGlob($dir . '/*.txt')));
$zip->close();

$zip = new ZipArchive();
$zip->open($archive);
var_dump($zip->numFiles);
var_dump($zip->getFromName($src) === file_get_contents($src));
$zip->close();
"#, &[], &[]);
    assert_eq!(out, r#"-- no options --
bool(true)
bool(true)
bool(true)
-- empty options --
bool(true)
bool(true)
bool(true)
-- overwrites an existing entry --
bool(true)
int(1)
bool(true)"#);
}
