/// Replays php-src `bug47667.phpt`.
#[test]
fn test_php_src_zip_bug47667() {
    if skip_without_zip_native("test_php_src_zip_bug47667") { return; }
    let out = run_case(r#"<?php
$thisdir = __DIR__;
$filename = $thisdir . "/bug47667.zip";

$zip = new ZipArchive();
if ($zip->open($filename, ZipArchive::CREATE) !== true) {
    exit(1);
} else {
    $zip->addFromString('foo.txt', 'foo bar foobar');
    $zip->close();
}

for ($i = 0; $i < 10; $i++) {
    $zip = new ZipArchive();
    if ($zip->open($filename, ZipArchive::OVERWRITE) !== true) {
        exit(1);
    }
    $zip->addFromString("foo_{$i}.txt", 'foo bar foobar');
    $zip->close();
}

$zip = new ZipArchive();
if ($zip->open($filename, ZipArchive::CREATE) !== true) {
    exit(1);
}

echo "files: " , $zip->numFiles;
$zip->close();

unlink($filename);
"#, &[], &[]);
    assert_eq!(out, r#"files: 1"#);
}
