/// Replays php-src `oo_progress_trampoline.phpt`.
#[test]
fn test_php_src_zip_oo_progress_trampoline() {
    if skip_without_zip_native("test_php_src_zip_oo_progress_trampoline") { return; }
    let out = run_case(r#"<?php
$dirname = dirname(__FILE__) . '/';
$file = $dirname . '__tmp_oo_progress_trampoline.zip';

class TrampolineTest {
    public static $progressCalls = 0;
    public function __call(string $name, array $arguments): void {
        echo 'Trampoline for ', $name, PHP_EOL;
        if ($name === 'trampolineThrow') {
            throw new Exception('boo');
        }
        var_dump($arguments);
        $r = $arguments[0];
        self::$progressCalls = self::$progressCalls + 1; if (self::$progressCalls === 1) echo "start\n";
        if (self::$progressCalls === 2) echo "end\n";
    }
}
$o = new TrampolineTest();
$callback = function ($value = null) use ($o) { return $value === null ? $o->trampoline() : $o->trampoline($value); };
$callbackThrow = function () use ($o) { return $o->trampolineThrow(); };


$zip = new ZipArchive;
if (!$zip->open($file, ZIPARCHIVE::CREATE)) {
    exit(1);
}
var_dump($zip->registerProgressCallback(0.5, $callback));
var_dump($zip->addFromString('foo', 'entry #1'));
var_dump($zip->close());

echo "Set trampoline after closed Archive:\n";
try {
    var_dump($zip->registerProgressCallback(0.5, $callback));
} catch (Throwable $e) {
    echo $e::class, ': ', $e->getMessage(), PHP_EOL;
}

unlink($file);
unset($zip);

$zip = new ZipArchive;
if (!$zip->open($file, ZIPARCHIVE::CREATE)) {
    exit(1);
}

var_dump($zip->registerProgressCallback(0.5, $callbackThrow));
var_dump($zip->addFromString('foo', 'entry #1'));
try {
    var_dump($zip->close());
} catch (Throwable $e) {
    echo $e::class, ': ', $e->getMessage(), PHP_EOL;
}
unlink($file);
unset($zip);
echo 'Done
';"#, &[(r#"date.timezone"#, r#"UTC"#)], &[]);
    assert_eq!(out, r#"bool(true)
bool(true)
Trampoline for trampoline
array(1) {
  [0]=>
  float(0)
}
start
Trampoline for trampoline
array(1) {
  [0]=>
  float(1)
}
end
bool(true)
Set trampoline after closed Archive:
ValueError: Invalid or uninitialized Zip object
bool(true)
bool(true)
Trampoline for trampolineThrow
Exception: boo
Done"#);
}
